// Generated by scripts/generate-flags.ts before dev and build.
import flagsJson from "@/lib/flags.generated.json"
import { cn } from "@/lib/utils"

// Country code to a data URL of its circle flag.
const flags: Record<string, string> = flagsJson

interface FlagProps {
  countryCode?: string
  size?: number
  className?: string
}

export function Flag({ countryCode, size = 22, className }: FlagProps) {
  const src = countryCode ? flags[countryCode] : undefined

  return (
    <div
      className={cn("flex shrink-0", className)}
      style={{ width: size, height: size }}
    >
      {src ? (
        // A data URL bundled with the app: nothing to optimize or wait for.
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={src}
          alt=""
          width={size}
          height={size}
          className="rounded-full border"
        />
      ) : null}
    </div>
  )
}
